python - <<'PY'
import numpy as np,json
from PIL import Image
p='/app/runs/initial'; m=json.load(open(p+'/meta.json'))
for cam in ['egocentric_mirrored_camera','over_shoulder_left_camera','wrist_cam']:
 im=np.array(Image.open(p+'/last/'+cam+'.jpg')); d=np.load(p+'/last_depth_'+cam+'.npy'); c=m['cameras'][cam]; K=np.array(c['intrinsic_cv']); E=np.array(c['extrinsic_cv']);
 R,t=E[:,:3],E[:,3];
 yellow=(im[:,:,0]>140)&(im[:,:,1]>100)&(im[:,:,2]<120)&(im[:,:,0]>im[:,:,2]*1.6)
 yy,xx=np.where(yellow & (d>0));
 if len(xx):
  zz=d[yy,xx]; pts=(R.T@np.stack(((xx-K[0,2])*zz/K[0,0],(yy-K[1,2])*zz/K[1,1],zz),axis=0)-R.T@t[:,None]).T
  print(cam,'yellow pixels',len(xx),'uv med',np.median(xx),np.median(yy),'world med',np.median(pts,axis=0),'world range',np.quantile(pts,[.05,.95],axis=0))
 for x,y in [(432,240),(430,280),(200,200),(650,200),(700,340),(550,420)]:
  if x>=im.shape[1] or y>=im.shape[0]:continue
  z=d[y,x]; pt=R.T@np.array([(x-K[0,2])*z/K[0,0],(y-K[1,2])*z/K[1,1],z])-R.T@t
  print((x,y),'depth',z,'world',np.round(pt,3),'rgb',im[y,x])
